AMOUNT_RE = re.compile(r"\d{1,3}(?:,\d{3})+\.\d{2}|\d+\.\d{2}")


def normalise_amount(s: str) -> str:
    return s.replace(",", "")


def _clean_numeric_spacing(line: str) -> str:
    """Collapse OCR spaces that appear inside numbers like '100. 62'."""
    # Remove spaces around decimal point: '100. 62' -> '100.62'
    line = re.sub(r"(\d)\s*\.\s*(\d{2})(?!\d)", r"\1.\2", line)
    # Remove spaces around comma in thousands grouping: '1, 234' -> '1,234'
    line = re.sub(r"(\d)\s*,\s*(\d{3})(?!\d)", r"\1,\2", line)
    return line


def extract_amounts(line: str):
    """Return list of (match_start, amount_string) in reading order."""
    cleaned = _clean_numeric_spacing(line)
    return [(m.start(), normalise_amount(m.group(0))) for m in AMOUNT_RE.finditer(cleaned)]"}: Editing /app/workspace/extract.py

